frappe.listview_settings['Daily Time Record'] = {
    refresh: function(listview) {
        // console.log("List View Loaded");

        frappe.call({
            method: "cvsu_hris.cvsu_hris.doctype.daily_time_record.daily_time_record.get_year_options",
            callback: function(response) {
                // console.log("API Method Called");

                if (response.message) {
                    // console.log("Updating List Filter with:", response.message);

                    let year_field = frappe.meta.get_docfield("Daily Time Record", "year", listview.page);
                    if (year_field) {
                        year_field.options = response.message.join('\n');
                        // console.log("Year field options updated:", year_field.options);

                        // 🚀 Force UI to reload filters
                        listview.page.fields_dict.year.df.options = response.message.join('\n');
                        listview.page.fields_dict.year.refresh();
                        listview.refresh();
                    } 
                }
            }
        });
    }
};

frappe.ui.form.on('Employee', {
