	//On Change of Designation 
	designation: (frm) =>{
	    //Get only all manually added skills
	    let not_imported = frm.doc.custom_special_skills_hobbies.filter((skill) => !skill.is_imported);

	    //Set the contents of the skills and hobbies to be all manually addedd
        frm.set_value('custom_special_skills_hobbies',not_imported);

	    if (frm.doc.designation) {
