				designation.skills.forEach(designation_skill => {
					let row = frm.add_child('custom_special_skills_hobbies', {
                        skills_hobbies:designation_skill.skill,
                        is_imported: true // Not Manually Added Skill
					});
				});

				refresh_field('custom_special_skills_hobbies');
			});
		}
	}
})

