const rel_ranks = {
    'Spouse': 1,
    'Father': 2,
    'Mother': 2,
    'Children': 3
};

const education_ranks = {
    'Graduate Studies': 1,
    'College': 1,
    'Vocational/Trade Course': 1,
    'Secondary': 1,
    'Elementary': 1

}

let family_sorter = (m1, m2) => {
   let rel_rank1 = rel_ranks[m1.relationship], rel_rank2 = rel_ranks[m2.relationship];

   if(rel_rank1 === rel_rank2){
       let dob1 = Date.parse(m1.date_of_birth), dob2 = Date.parse(m2.date_of_birth);
       return dob1 - dob2;
   }else{
       return rel_rank1 - rel_rank2;
   }
};

let education_sorter = (e1, e2) => {
    let edu_rank1 = education_ranks[e1.custom_education_level], edu_rank2 = education_ranks[e2.custom_education_level]

    if (edu_rank1 == edu_rank2){
        let period_to1 = parseInt(e1.custom_education_period_of_attendance_to), period_to2 = parseInt(e2.custom_education_period_of_attendance_to); 
        let period_from1 = parseInt(e1.custom_education_period_of_attendance_from), period_from2 = parseInt(e2.custom_education_period_of_attendance_from); 

        if (period_to1 === period_to2 ){
            return period_from2 - period_from1;
        }else{
            return period_to2 - period_to1;
        }
    }else{
        return edu_rank1 - edu_rank2;
    }
}

let eligibility_sorter = (e1, e2) => {
    let exam_date1 = Date.parse(e1.civil_service_date_examination), exam_date2 = Date.parse(e2.civil_service_date_examination); 
    return exam_date2 - exam_date1;
}

let external_work_sorter = (w1, w2) => {
    let period_to1 = Date.parse(w1.custom_ew_to_date), period_to2 = Date.parse(w2.custom_ew_to_date); 
    let period_from1 = Date.parse(w1.custom_ew_from_date), period_from2 = Date.parse(w2.custom_ew_from_date); 

    if (period_to1 === period_to2 ){
        return period_from2 - period_from1;
    }else{
        return period_to2 - period_to1;
    }
}

let internal_work_sorter = (w1, w2) => {
    let period_to1 = Date.parse(w1.to_date), period_to2 = Date.parse(w2.to_date); 
    let period_from1 = Date.parse(w1.from_date), period_from2 = Date.parse(w2.from_date); 

    if (period_to1 === period_to2 ){
        return period_from2 - period_from1;
    }else{
        return period_to2 - period_to1;
    }
}

let voluntary_work_sorter = (w1, w2) => {
    let period_to1 = Date.parse(w1.voluntary_work_inclusive_dates_to), period_to2 = Date.parse(w2.voluntary_work_inclusive_dates_to); 
    let period_from1 = Date.parse(w1.voluntary_work_inclusive_dates_from), period_from2 = Date.parse(w2.voluntary_work_inclusive_dates_from); 

    if (period_to1 === period_to2 ){
        return period_from2 - period_from1;
    }else{
        return period_to2 - period_to1;
    }
}

let training_sorter = (t1, t2) => {
    let period_to1 = Date.parse(t1.training_program_inclusive_dates_attendance_to), period_to2 = Date.parse(t2.training_program_inclusive_dates_attendance_to); 
    let period_from1 = Date.parse(t1.training_program_inclusive_dates_attendance_from), period_from2 = Date.parse(t2.training_program_inclusive_dates_attendance_from); 

    if (period_to1 === period_to2 ){
        return period_from2 - period_from1;
    }else{
        return period_to2 - period_to1;
    }
}

let skill_sorter = (s1, s2) => {
    let e1 = s1.skills_hobbies.toUpperCase(), e2 = s2.skills_hobbies.toUpperCase();

    if (e1 < e2 ){
        return -1;
    }else if (e1 > e2 ){
        return 1
    }else{
        return 0;
    }
}

let recognition_sorter = (r1, r2) => {
    let e1 = r1.other_information_non_academic_distinctions_recognition.toUpperCase(), e2 = r2.other_information_non_academic_distinctions_recognition.toUpperCase();

    if (e1 < e2 ){
        return -1;
    }else if (e1 > e2 ){
        return 1
    }else{
        return 0;
    }
}

let organization_sorter = (o1, o2) => {
    let e1 = o1.other_information_membership_association_organization.toUpperCase(), e2 = o2.other_information_membership_association_organization.toUpperCase();

    if (e1 < e2 ){
        return -1;
    }else if (e1 > e2 ){
        return 1
    }else{
        return 0;
    }
}

function sort_child_table(t, f = undefined) {
    t.sort(f);
    t.forEach((m,indx)=>{ m.idx = indx + 1 })
}

frappe.ui.form.on('Employee', {
	onload(frm) {
	    sort_child_table(frm.doc.custom_family, family_sorter);
	    sort_child_table(frm.doc.education, education_sorter);
	    sort_child_table(frm.doc.custom_civil_service_eligibility_, eligibility_sorter);
	    sort_child_table(frm.doc.external_work_history, external_work_sorter);
	    sort_child_table(frm.doc.internal_work_history, internal_work_sorter);
	    sort_child_table(frm.doc.custom_voluntary_work_, voluntary_work_sorter);
	    sort_child_table(frm.doc.custom_training_programs_attended_, training_sorter);
	    sort_child_table(frm.doc.custom_special_skills_hobbies, skill_sorter);
	    sort_child_table(frm.doc.custom_non_academic_distinctions_recognition, recognition_sorter);
	    sort_child_table(frm.doc.custom_membership_association_organization, organization_sorter);
	}
})

