});

frappe.ui.form.on('Daily Time Record', {
    onload: function(frm) {
        let currentDate = new Date();
        let currentYear = currentDate.getFullYear();
        
        // Manually define month names (instead of using frappe.datetime.months)
        let monthNames = [
            "January", "February", "March", "April", "May", "June", 
            "July", "August", "September", "October", "November", "December"
        ];
        
        let currentMonth = monthNames[currentDate.getMonth()]; // Get month name

        // Populate Month field options
        frm.set_df_property('month', 'options', monthNames.join('\n'));

        // Populate Year field options (10 years back & 10 years ahead)
        let yearOptions = [];
        for (let i = currentYear - 10; i <= currentYear + 10; i++) {
            yearOptions.push(i.toString());
        }
        frm.set_df_property('year', 'options', yearOptions.join('\n'));

        // Set default Month and Year
        // frm.set_value('month', currentMonth);
        // frm.set_value('year', currentYear.toString());
    }
});

