function toggle_mandatory_fields(frm) {
    // -----------------------------------
    // 1) HANDLE PARENT FIELDS
    // -----------------------------------
    frm.meta.fields.forEach(df => {
        if (["Section Break", "Column Break", "Table"].includes(df.fieldtype)) return;

        // Preserve original required state
        if (df.__original_reqd === undefined) df.__original_reqd = !!df.reqd;

        // Set parent fields based on status
        frm.set_df_property(df.fieldname, "reqd", frm.doc.status === "Left" ? false : df.__original_reqd);
    });

    // Refresh the whole form to apply changes
    frm.refresh_fields();
}

frappe.ui.form.on("Employee Schedule", {
    schedule_label(frm) {
        toggle_child_mandatory(frm);
    },

    refresh(frm) {
        toggle_child_mandatory(frm);
    }
});


function toggle_child_mandatory(frm) {
    let remove_required = frm.doc.schedule_label === "Overtime";

    frm.fields_dict["custom_detailed_schedule"].grid.update_docfield_property(
        "start_time",
        "reqd",
        !remove_required
    );

    frm.fields_dict["custom_detailed_schedule"].grid.update_docfield_property(
        "end_time",
        "reqd",
        !remove_required
    );

    frm.refresh_field("custom_detailed_schedule");
}

frappe.ui.form.on("Employee", {
    status(frm) {
        if (frm.doc.status === "Left") {
            // Make "reason_for_leaving" mandatory
            frm.set_df_property("custom_reason_for_leaving_cvsu", "reqd", true);

            // Make "relieving_date" non-mandatory
            frm.set_df_property("relieving_date", "reqd", false);

        } else {
            // Restore original state for other statuses
            frm.set_df_property("custom_reason_for_leaving_cvsu", "reqd", false);
            frm.set_df_property("relieving_date", "reqd", false); // or original state if needed

            // ---------------------------
            // Clear Employee Exit Tab Fields
            // ---------------------------
            const exit_fields = [
                "custom_reason_for_leaving_cvsu",
                "relieving_date",
                "resignation_letter_date",
                "held_on",
                "new_workplace",
                "leave_encashed",
                "encashment_date",
                "reason_for_leaving",
                "feedback",
                "lft",
                "rgt",
                "old_parent"
                // Add any other fields in the Employee Exit tab here
            ];

            exit_fields.forEach(fieldname => {
                if (frm.doc.hasOwnProperty(fieldname)) {
                    frm.set_value(fieldname, null);
                }
            });
        }

        // Refresh fields to update the UI
        frm.refresh_field("custom_reason_for_leaving_cvsu");
        frm.refresh_field("relieving_date");
    }
});

